TESTPLAN_COLS = ["Index","SS / Module","Feature","Test Case Name","Test Description","Speed","Mode","Memory Start Offset","Memory End Offset","Remarks","Test Steps / Procedure","Impacted Registers","Validation / Acceptance Criteria","Code Generation"]
METADATA_COLS = ["Index","Test Case Name","Meta Test Description","Meta Test Steps / Procedure","Meta Impacted Registers","Meta Validation / Acceptance Criteria","Meta Headers","Meta Macros","Meta Arrays"]

def apply_formatting(ws, cols, nrows):
    header_font = Font(bold=True, color="FFFFFFFF")
    header_fill = PatternFill(start_color="FF4472C4", end_color="FF4472C4", fill_type="solid")
    wrap = Alignment(wrap_text=True, vertical="top")
    for idx, col in enumerate(cols, 1):
        cell = ws.cell(row=1, column=idx, value=col)
        cell.font = header_font
        cell.fill = header_fill
        cell.alignment = wrap
    for r in range(2, nrows + 2):
        for c in range(1, len(cols) + 1):
            ws.cell(row=r, column=c).alignment = wrap
    ws.freeze_panes = "A2"
    for idx, col in enumerate(cols, 1):
        max_len = len(col)
        for r in range(2, nrows + 2):
            v = ws.cell(row=r, column=idx).value
            if v is not None:
                l = min(len(str(v)), 80)
                if l > max_len:
                    max_len = l
        ws.column_dimensions[get_column_letter(idx)].width = min(max(max_len + 2, 12), 60)

def main():
    ist = timezone(timedelta(hours=5, minutes=30))
    ts = datetime.now(ist).strftime("%Y%m%d_%H%M%S")
    filename = f"PCIE_TestPlan_{ts}.xlsx"
    out_dir = "Test_Output/PCIE/TestPlan"
    os.makedirs(out_dir, exist_ok=True)
    out_path = os.path.join(out_dir, filename)

    wb = Workbook()
    ws1 = wb.active
    ws1.title = "TestPlan"
    for r_idx, row in enumerate(JSON_DATA, 2):
        for c_idx, col in enumerate(TESTPLAN_COLS, 1):
            ws1.cell(row=r_idx, column=c_idx, value=row.get(col, ""))
    apply_formatting(ws1, TESTPLAN_COLS, len(JSON_DATA))

    ws2 = wb.create_sheet("MetaData")
    for r_idx, row in enumerate(JSON_DATA, 2):
        for c_idx, col in enumerate(METADATA_COLS, 1):
            ws2.cell(row=r_idx, column=c_idx, value=row.get(col, ""))
    apply_formatting(ws2, METADATA_COLS, len(JSON_DATA))
    ws2.sheet_state = "veryHidden"

    wb.save(out_path)
    print(f"Wrote {out_path}")
    print(f"::set-output name=filename::{filename}")
    with open(os.environ.get("GITHUB_OUTPUT", "/dev/null"), "a") as f:
        f.write(f"filename={filename}\n")
        f.write(f"filepath={out_path}\n")

if __name__ == "__main__":
    main()
